package frontend

import (
	"embed"
	"encoding/json"
	"expvar"
	"fmt"
	"net"
	"net/http"
	"os"
	"path"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"
	"go.opentelemetry.io/otel/baggage"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/baggageutils"
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/httperr"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/notifications"
	"github.com/signadot/hotrod/pkg/tracing"
	"github.com/signadot/hotrod/services/location"
)

//go:embed web_assets/*
var assetFS embed.FS

// Server implements hotrod-frontend service
type Server struct {
	addr     string
	basepath string

	tracer       trace.TracerProvider
	logger       log.Factory
	location     location.Interface
	notification notifications.Interface
	dispatcher   *dispatcher
}

// NewServer creates a new frontend.Server
func NewServer(logger log.Factory) *Server {
	// get tracer provider for the frontend
	tracerProvider := tracing.InitOTEL("frontend", logger)

	// get location client
	locationClient := location.NewClient(tracerProvider, logger, config.GetLocationAddr())

	// get notification handler
	notificationHandler := notifications.NewNotificationHandler(tracerProvider, logger)

	// get a dispatcher
	dispatcher := newDispatcher(tracerProvider, logger, locationClient)

	return &Server{
		addr:     net.JoinHostPort("0.0.0.0", config.GetFrontendBindPort()),
		basepath: config.GetFrontendBasepath(),

		tracer:       tracerProvider,
		logger:       logger,
		location:     locationClient,
		notification: notificationHandler,
		dispatcher:   dispatcher,
	}
}

// Run starts the frontend server
func (s *Server) Run() error {
	mux := s.createServeMux()
	s.logger.Bg().Info("Starting", zap.String("address", "http://"+path.Join(s.addr, s.basepath)))
	server := &http.Server{
		Addr:              s.addr,
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
	}
	return server.ListenAndServe()
}

func (s *Server) createServeMux() http.Handler {
	mux := tracing.NewServeMux(true, s.tracer, s.logger)
	p := path.Join("/", s.basepath)
	mux.Handle(path.Join(p, "/dispatch"), http.HandlerFunc(s.dispatch))
	mux.Handle(path.Join(p, "/notifications"), http.HandlerFunc(s.notifications))
	mux.Handle(path.Join(p, "/debug/vars"), expvar.Handler())       // expvar
	mux.Handle(path.Join(p, "/metrics"), promhttp.Handler())        // Prometheus
	mux.Handle(path.Join(p, "/splash"), http.HandlerFunc(s.splash)) // Prometheus
	staticFileServer := http.FileServer(http.FS(assetFS))

	mux.Handle("/web_assets/", http.StripPrefix("", staticFileServer))

	mux.Handle("/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" {
			indexContent, err := assetFS.ReadFile("web_assets/index.html")
			if err != nil {
				http.Error(w, "Internal server error", http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(indexContent)
		} else {
			staticFileServer.ServeHTTP(w, r)
		}
	}))
	mux.Handle(path.Join(p, "/healthz"), http.HandlerFunc(func(resp http.ResponseWriter, req *http.Request) {
		s.logger.For(req.Context()).Info("/healthz")
		resp.Write([]byte("ok"))
	}))
	return mux
}

func (s *Server) splash(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	// get all stored locations
	locations, err := s.location.List(ctx)
	if err != nil {
		httperr.HandleError(w, err, http.StatusInternalServerError)
		return
	}

	// load data for the template
	data := struct {
		Locations   []location.Location
		TitleSuffix string
	}{locations, os.Getenv("FRONTEND_TITLE_SUFFIX")}

	s.writeResponse(data, w, r)
}

func (s *Server) dispatch(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	// decode request body
	var dispatchReq DispatchRequest
	err := json.NewDecoder(r.Body).Decode(&dispatchReq)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("error parsing request body", zap.Error(err))
		return
	}

	// get request context
	reqContext := &notifications.RequestContext{
		ID:                dispatchReq.RequestID,
		SessionID:         dispatchReq.SessionID,
		PickupLocationID:  dispatchReq.PickupLocationID,
		DropoffLocationID: dispatchReq.DropoffLocationID,
	}

	// inject the request context into baggage and update the current context
	bag, err := baggageutils.InjectRequestContext(ctx, reqContext)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot inject request context into baggage", zap.Error(err))
		return
	}
	ctx = baggage.ContextWithBaggage(ctx, *bag)

	// send frontend-dispatching-driver notification
	s.logger.For(ctx).Info("Dispatching driver", zap.Any("request", dispatchReq))
	s.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-frontend-dispatching-driver", dispatchReq.RequestID),
		Timestamp: time.Now(),
		Context:   s.notification.NotificationContext(reqContext, baggageutils.GetRoutingKey(ctx)),
		Body:      "Processing dispatch driver request",
	})

	// resolve locations
	pickupLoc, dropoffLoc, err := s.dispatcher.ResolveLocations(ctx, &dispatchReq)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("couldn't resolve locations", zap.Error(err))
		return
	}

	// dispatch a driver request
	err = s.dispatcher.DispatchDriver(ctx, &dispatchReq, pickupLoc, dropoffLoc)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("couldn't trigger dispatch request", zap.Error(err))
		return
	}
	s.writeResponse(map[string]interface{}{}, w, r)
}

func (s *Server) notifications(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))
	if err := r.ParseForm(); httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	sessionIDStr := r.Form.Get("sessionID")
	if sessionIDStr == "" {
		http.Error(w, "Missing required 'sessionID' parameter", http.StatusBadRequest)
		return
	}
	sessionID, err := strconv.Atoi(sessionIDStr)
	if err != nil {
		http.Error(w, "Parameter 'sessionID' is not an integer", http.StatusBadRequest)
		return
	}

	cursorStr := r.Form.Get("cursor")
	if cursorStr == "" {
		http.Error(w, "Missing required 'cursor' parameter", http.StatusBadRequest)
		return
	}
	cursor, err := strconv.Atoi(cursorStr)
	if err != nil {
		http.Error(w, "Parameter 'cursor' is not an integer", http.StatusBadRequest)
		return
	}

	data, err := s.notification.List(ctx, uint(sessionID), cursor)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}

	s.writeResponse(data, w, r)
}

func (s *Server) writeResponse(response interface{}, w http.ResponseWriter, r *http.Request) {
	data, err := json.Marshal(response)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(r.Context()).Error("cannot marshal response", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}
package frontend

type DispatchRequest struct {
	SessionID         uint
	RequestID         uint
	PickupLocationID  uint
	DropoffLocationID uint
}
package frontend

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/IBM/sarama"
	"github.com/dnwe/otelsarama"
	"github.com/signadot/hotrod/pkg/kafka"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
	"github.com/signadot/hotrod/services/driver"
	"github.com/signadot/hotrod/services/location"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"
)

type dispatcher struct {
	tracer   trace.Tracer
	logger   log.Factory
	location location.Interface
	producer sarama.SyncProducer
}

func newDispatcher(tracerProvider trace.TracerProvider, logger log.Factory,
	location location.Interface) *dispatcher {

	logger = logger.With(zap.String("component", "dispatcher"))

	// create a new tracer provider for kafka
	kafkaTracerProvider := tracing.InitOTEL("kafka", logger)
	producerTicker := time.NewTicker(100 * time.Millisecond)
	defer producerTicker.Stop()
	var (
		producer sarama.SyncProducer
		err      error
	)
	for {
		// get a kafka producer
		producer, err = kafka.GetSyncProducer("hotrod-frontend", kafkaTracerProvider)
		if err != nil {
			logger.Bg().Error("error getting kafka producer (will retry)")
			<-producerTicker.C
		} else {
			break
		}
	}

	return &dispatcher{
		tracer:   tracerProvider.Tracer("dispatcher"),
		logger:   logger,
		location: location,
		producer: producer,
	}
}

func (d *dispatcher) ResolveLocations(ctx context.Context,
	req *DispatchRequest) (*location.Location, *location.Location, error) {
	ctx, span := d.tracer.Start(ctx, "ResolveLocations", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		attribute.
			Key("session.id").
			Int(int(req.SessionID)),
	)
	defer span.End()

	// resolve locations
	pickupLoc, err := d.location.Get(ctx, int(req.PickupLocationID))
	if err != nil {
		return nil, nil, fmt.Errorf("couldn't resolve pickup location, %w", err)
	}

	dropoffLoc, err := d.location.Get(ctx, int(req.DropoffLocationID))
	if err != nil {
		return nil, nil, fmt.Errorf("couldn't resolve dropoff location, %w", err)
	}

	d.logger.For(ctx).Info("Found locations", zap.Any("pickupLocation", pickupLoc),
		zap.Any("dropoffLocation", dropoffLoc))
	return pickupLoc, dropoffLoc, nil
}

func (d *dispatcher) DispatchDriver(ctx context.Context, req *DispatchRequest,
	pickupLoc, dropoffLoc *location.Location) error {
	ctx, span := d.tracer.Start(ctx, "DispatchDriver", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		attribute.
			Key("session.id").
			Int(int(req.SessionID)),
	)
	defer span.End()

	driverRequest := driver.DispatchRequest{
		PickupLocation:  pickupLoc,
		DropoffLocation: dropoffLoc,
	}
	msgBody, err := json.Marshal(driverRequest)
	if err != nil {
		return fmt.Errorf("couldn't encode driver request, %w", err)
	}

	msg := &sarama.ProducerMessage{
		Topic: kafka.DispatchDriverTopic,
		Key:   sarama.StringEncoder("message"),
		Value: sarama.StringEncoder(string(msgBody)),
	}
	otel.GetTextMapPropagator().Inject(ctx, otelsarama.NewProducerMessageCarrier(msg))

	partition, offset, err := d.producer.SendMessage(msg)
	if err != nil {
		return fmt.Errorf("couldn't publish message to kafka, %w", err)
	}

	d.logger.For(ctx).Info("Published message to kafka",
		zap.Any("pickupLocation", pickupLoc),
		zap.Any("dropoffLocation", dropoffLoc),
		zap.Any("partition", partition),
		zap.Any("offset", offset),
	)
	return nil
}

