package location

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"

	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
)

type Client struct {
	logger   log.Factory
	client   *tracing.HTTPClient
	hostPort string
}

func NewClient(tracerProvider trace.TracerProvider, logger log.Factory, addr string) *Client {
	return &Client{
		logger:   logger,
		client:   tracing.NewHTTPClient(tracerProvider),
		hostPort: addr,
	}
}

func (c *Client) Get(ctx context.Context, locationID int) (*Location, error) {
	c.logger.For(ctx).Info("Getting location", zap.Int("location_id", locationID))

	url := fmt.Sprintf("http://"+c.hostPort+"/location?locationID=%d", locationID)
	var location Location
	if err := c.client.GetJSON(ctx, "/location", url, &location); err != nil {
		return nil, err
	}
	return &location, nil
}

func (c *Client) List(ctx context.Context) ([]Location, error) {
	c.logger.For(ctx).Info("Getting locations")

	url := fmt.Sprintf("http://%s/locations", c.hostPort)
	fmt.Println(url)
	var locations []Location
	if err := c.client.GetJSON(ctx, "/locations", url, &locations); err != nil {
		return nil, err
	}
	return locations, nil
}

func (c *Client) Put(ctx context.Context, location *Location) error {
	c.logger.For(ctx).Info("PUT location", zap.Int64("location_id", location.ID))

	url := fmt.Sprintf("http://%s/location?locationID=%d", c.hostPort, location.ID)
	fmt.Println(url)
	var outLocation Location
	if err := c.putJSON(ctx, url, location, outLocation); err != nil {
		return err
	}
	return nil
}

func (c *Client) putJSON(ctx context.Context, url string, reqIn, respOut interface{}) error {
	d, err := json.Marshal(reqIn)
	if err != nil {
		return err
	}
	req, err := http.NewRequest("PUT", url, bytes.NewBuffer(d))
	req.Header.Add("Content-type", "application/json")
	if err != nil {
		return err
	}
	req = req.WithContext(ctx)

	res, err := c.client.Client.Do(req)
	if err != nil {
		return err
	}

	defer res.Body.Close()

	if res.StatusCode >= 400 {
		body, err := io.ReadAll(res.Body)
		if err != nil {
			return err
		}
		return errors.New(string(body))
	}
	decoder := json.NewDecoder(res.Body)
	return decoder.Decode(respOut)
}

package driver

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"sync"

	"github.com/signadot/hotrod/pkg/config"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/delay"
	"github.com/signadot/hotrod/pkg/log"
)

type driverStore struct {
	errorSimulator
	tracer trace.Tracer
	logger log.Factory
}

func newDriverStore(tracer trace.Tracer, logger log.Factory) *driverStore {
	return &driverStore{
		tracer: tracer,
		logger: logger,
		errorSimulator: errorSimulator{
			errorFreq: config.GetDriverStoreErrorFreq(),
		},
	}
}

func (s *driverStore) FindDriverIDs(ctx context.Context) []string {
	ctx, span := s.tracer.Start(ctx, "FindDriverIDs", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	// simulate delay
	delay.Sleep(config.GetDriverStoreFindDelay(), config.GetDriverStoreFindStdDev())

	drivers := make([]string, 10)
	for i := range drivers {
		// #nosec
		drivers[i] = fmt.Sprintf("%sT7%05dC%s",
			config.GetDriverIDPrefix(), rand.Int()%100000, config.GetDriverIDSuffix())
	}
	s.logger.For(ctx).Info("Found drivers", zap.Strings("drivers", drivers))
	return drivers
}

func (s *driverStore) GetDriversLocation(ctx context.Context, driverIDs []string) ([]*Driver, error) {
	ctx, span := s.tracer.Start(ctx, "GetDriversLocation", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	drivers := make([]*Driver, len(driverIDs))
	for i, driverID := range driverIDs {
		var drv Driver
		var err error
		for i := 0; i < 3; i++ {
			drv, err = s.GetDriver(ctx, driverID)
			if err == nil {
				break
			}
			s.logger.For(ctx).Error("Retrying GetDriver after error",
				zap.Int("retry_no", i+1), zap.Error(err))
		}
		if err != nil {
			s.logger.For(ctx).Error("Failed to get driver after 3 attempts", zap.Error(err))
			span.SetStatus(codes.Error, err.Error())
			return nil, err
		}
		drivers[i] = &Driver{
			DriverID:    driverID,
			Coordinates: drv.Coordinates,
		}
	}
	return drivers, nil
}

func (s *driverStore) GetDriver(ctx context.Context, driverID string) (Driver, error) {
	ctx, span := s.tracer.Start(ctx, "GetDriver", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		attribute.
			Key("driver.id").
			String(driverID),
	)
	defer span.End()

	// simulate delay
	delay.Sleep(config.GetDriverStoreGetDelay(), config.GetDriverStoreGetStdDev())

	if err := s.checkError(); err != nil {
		// simulated error
		span.SetStatus(codes.Error, err.Error())
		s.logger.For(ctx).Error("error getting driver from ID", zap.String("driver_id", driverID), zap.Error(err))
		return Driver{}, err
	}

	return Driver{
		DriverID:    driverID,
		Coordinates: fmt.Sprintf("%d,%d", rand.Int()%1000, rand.Int()%1000),
	}, nil
}

var errTimeout = errors.New("driver store timeout")

type errorSimulator struct {
	sync.Mutex
	errorFreq      int
	countTillError int
}

func (es *errorSimulator) checkError() error {
	if es.errorFreq == 0 {
		return nil // errors disabled
	}
	es.Lock()
	es.countTillError--
	if es.countTillError > 0 {
		es.Unlock()
		return nil
	}
	es.countTillError = es.errorFreq
	es.Unlock()
	// add more delay for "timeout"
	delay.Sleep(config.GetDriverStoreGetDelay(), config.GetDriverStoreGetStdDev())
	return errTimeout
}
import {MainLayout} from "../components/layouts";
import {
    Box,
    Button,
    Card,
    CardBody,
    CardHeader,
    Heading,
    HStack,
    Stack,
    StackDivider,
    Text,
    useDisclosure,
    useToast,
} from "@chakra-ui/react";
import styles from "./home.module.css";

import {Logs} from "../components/features/logs/logs.tsx";
import {Map} from "../components/features/map/map.tsx";
import {useSession} from "../context/sessionContext/context.tsx";
import {useEffect, useRef, useState} from "react";
import {apiGet, apiPost} from "../services/http.ts";
import {Locations} from "../types/location.ts";
import {LocationSelect} from "../components/common/locationSelect/locationSelect.tsx";
import {useLogs} from "../hooks/useLogs.tsx";
import {NotificationResponse} from "../types/notifications.ts";
import {useGetRequestArrival} from "../hooks/useGetRequestArrival.tsx";
import Countdown, {CountdownRenderProps} from "react-countdown";

const countdownRenderer = ({minutes, seconds, driverName, driverPlate, props }: CountdownRenderProps & { driverName: string, driverPlate: string }) => {
    if (minutes === 0 && seconds === 0) {
        return <Text>{driverName} arrived</Text>;
    } else {
        return <Text as="b">The driver {driverName} ({driverPlate}) will arrive in {props.overtime ? "-" : ""}{minutes.toString().padStart(2, "0")}:{seconds.toString().padStart(2, "0")}</Text>;
    }
};

export const HomePage = () => {
    const session = useSession();
    const notificationCursorRef = useRef(-1);
    const [locations, setLocations] = useState<Locations | undefined>();

    const [selectedLocations, setSelectedLocations] = useState({pickupId: -1, dropoffId: -1});
    const {logs, addNewLog, addErrorEntry, addInformationEntry} = useLogs();
    const lastRequestedDrive = useGetRequestArrival(logs);

    const logsModal = useDisclosure();
    const toast = useToast();

    useEffect(() => {
        const fetchLocations = async () => {
            const locations = await apiGet<Locations>('/splash');
            setLocations(locations)
        }

        fetchLocations();
    }, []);

    useEffect(() => {
        const pollNotifications = async () => {
            const cursor = notificationCursorRef.current;
            const nonse = Math.random();
            const url = `/notifications?sessionID=${session.sessionID}&cursor=${cursor}&nonse=${nonse}`
            const notification = await apiGet<NotificationResponse>(url);

            notificationCursorRef.current = notification.cursor;

            notification.notifications.forEach(notification => {
                addInformationEntry(notification.context.request.id, {
                    date: new Date(notification.timestamp),
                    service: notification.context.baselineWorkload,
                    status: notification.body,
                    sandboxName: notification.context.sandboxName,
                })
            });
        }

        const intervalID = setInterval(pollNotifications, 2000);

        return () => {
            clearInterval(intervalID);
        }

    }, []);

    if (!locations) {
        return (
            <MainLayout titleSuffix="">
                <Heading>Loading</Heading>
            </MainLayout>
        )
    }

    const handleRequestDrive = async () => {
        const {getLastRequestID, sessionID} = session;
        const requestID = getLastRequestID();

        const {pickupId, dropoffId} = selectedLocations;
        const data = {
            sessionID: sessionID,
            requestID: requestID,
            pickupLocationID: pickupId,
            dropoffLocationID: dropoffId
        }

        const pickupLocation = locations?.Locations.find(l => l.id === pickupId);
        const dropoffLocation = locations?.Locations.find(l => l.id === dropoffId);

        toast({
            title: 'Hotrod::Ride requested.',
            description: `Ride requested to ${dropoffLocation?.name}`,
            status: 'success',
            duration: 9000,
            isClosable: true,
            position: "top"
        });

        // Reset locations
        setSelectedLocations({pickupId: -1, dropoffId: -1});

        addNewLog(pickupLocation!, dropoffLocation!, requestID, {
            messageType: "info",
            service: 'browser',
            date: new Date(),
            status: 'Requesting a ride.'
        });

        try {
            await apiPost<{}>('/dispatch', data, {"baggage": `session=${sessionID}, request=${requestID}`});
        } catch (e) {
            addErrorEntry(requestID, {
                status: 'Error requesting a ride to frontend API',
                service: 'api',
                date: new Date(),
            })
        }
    }

    return (
        <MainLayout titleSuffix={locations.TitleSuffix}>
            <HStack alignItems='flex-start' p={4} gap={8} justifyContent='space-between' h='100%'>
                <Stack flexGrow={1} w='50%'>
                    <Card border={12} maxW={600}>
                        <CardHeader>
                            <Heading size='lg' textAlign='left'>
                                Go anywhere with HotROD
                            </Heading>
                            <Heading size='xs' textAlign='left'>
